<?php
require_once __DIR__.'/address.php';
final class PDSExtrasView {
    public static bool $paperEntry=false;
    public static function addresses(array $data,array $post=[]): void {
        $saved=PDSAddress::decode($data['home_address']??'');
        if(is_array($post['addresses']??null))$saved=array_merge($saved,$post['addresses']);
        $e=[PDSEditorView::class,'e'];
        ?><section class="pe-addresses pe-section"><h3>Home addresses</h3><p class="pe-help">Choose locations from the Philippine Statistics Authority PSGC. Enter your street and Purok/Sitio manually; no verified local list is installed.</p><input type="hidden" name="_pds_addresses" value="1"><input type="hidden" name="home_address" value="<?=$e($data['home_address']??'')?>"><?php foreach(['city_street','city_purok','city_barangay'] as $field):?><input type="hidden" name="<?=$field?>" value="<?=$e($data[$field]??'')?>"><?php endforeach;?>
        <?php foreach(['residential'=>'Residential address','permanent'=>'Permanent address'] as $key=>$title):$entry=is_array($saved[$key]??null)?$saved[$key]:[];$legacy=is_scalar($entry['legacy']??null)?(string)$entry['legacy']:PDSAddress::line($entry);$mode=$entry['mode']??'keep';if($key==='residential'&&$legacy===''&&!isset($data['id']))$mode='structured';if($key==='permanent'&&!isset($data['id']))$mode='structured';?>
        <?php if($key==='permanent'):?><label class="pe-copy-address"><input type="checkbox" name="addresses[same]" value="1" data-address-same <?=!empty($saved['same'])?'checked':''?>> Same as Residential Address</label><?php endif;?>
        <fieldset class="pe-address-block" data-address="<?=$key?>"><legend><?=$title?></legend><label class="pe-field"><span>Address entry</span><select name="addresses[<?=$key?>][mode]" data-address-mode><option value="structured" <?=$mode==='structured'?'selected':''?>>Choose Philippine locations</option><option value="keep" <?=$mode!=='structured'?'selected':''?>>Keep / enter a written address</option></select></label>
        <div data-address-legacy><label class="pe-field"><span>Written / previously saved address</span><textarea name="addresses[<?=$key?>][legacy]" rows="2" maxlength="2000"><?=$e($legacy)?></textarea></label><p class="pe-help">Saved text is kept as entered. It is not matched to a location automatically. Use this for an overseas address too.</p></div>
        <div data-address-structured><div class="pe-grid"><?php foreach(['region'=>'Region','province'=>'Province / geographic area','city'=>'City / municipality / district','barangay'=>'Barangay'] as $field=>$label):?><label class="pe-field"><span><?=$label?> *</span><select name="addresses[<?=$key?>][<?=$field?>]" data-address-level="<?=$field?>" data-saved-code="<?=$e($entry[$field]??'')?>"><option value="">Select <?=$label?></option></select></label><?php endforeach;?></div><div class="pe-grid"><label class="pe-field"><span>House number / Street</span><input name="addresses[<?=$key?>][street]" maxlength="255" autocomplete="address-line1" value="<?=$e($entry['street']??'')?>" placeholder="Enter the actual street"></label><label class="pe-field"><span>Purok / Sitio</span><input name="addresses[<?=$key?>][purok]" maxlength="255" autocomplete="address-line2" value="<?=$e($entry['purok']??'')?>" placeholder="Enter the actual Purok/Sitio"></label></div></div><p class="pe-help" data-address-status role="status"></p></fieldset><?php endforeach;?><p class="pe-help">PSGC release: 12 October 2026. Cities without a province are listed directly under their region.</p></section><?php
    }
    public static function languages(array $data): void {
        $selected=PDSEditorSchema::tokens($data['languages_spoken']??'');$other='';foreach($selected as &$value)if(preg_match('/^Others?:\s*(.*)$/iu',$value,$match)){$other=$match[1];$value='Others';}unset($value);
        $options=['Filipino','English','Cebuano / Bisaya','Hiligaynon','Waray','Ilocano','Kapampangan','Pangasinan','Bikol','Maranao','Maguindanaon','Tausug','Chavacano','Mandarin','Others'];$e=[PDSEditorView::class,'e'];
        $summary=$selected?implode(', ',$selected):'Choose languages';
        ?><div class="pe-language" data-language-picker><span id="peLanguagesLabel" class="pe-language-label">Languages spoken at home</span><input type="hidden" name="languages_spoken[]" value=""><details class="pe-language-menu"><summary aria-labelledby="peLanguagesLabel peLanguagesSummary"><span id="peLanguagesSummary" data-language-summary><?=$e($summary)?></span><span class="pe-language-chevron" aria-hidden="true"></span></summary><div class="pe-language-panel"><label class="pe-language-search"><span class="pe-language-sr">Search languages</span><input type="search" data-language-search placeholder="Search languages…" autocomplete="off"></label><fieldset class="pe-language-options"><legend class="pe-language-sr">Select all languages spoken at home</legend><?php foreach(array_unique(array_merge($options,$selected)) as $option):?><label class="pe-language-option" data-language-option><input type="checkbox" name="languages_spoken[]" value="<?=$e($option)?>" <?=in_array($option,$selected,true)?'checked':''?>><span><?=$e((in_array($option,$options,true)?'':'Recorded: ').$option)?></span></label><?php endforeach;?></fieldset><p class="pe-help" data-language-no-results hidden>No matching languages. Choose Others to specify a language.</p><div class="pe-language-footer"><span data-language-count aria-live="polite"><?=count($selected)?> selected</span><button type="button" data-language-clear>Clear selection</button></div></div></details><small>Select one or more languages. No Ctrl/Command key needed.</small><label class="pe-field" data-other-for="languages_spoken"><span>Other language (specify)</span><input name="languages_spoken_other" maxlength="180" value="<?=$e($data['languages_spoken_other']??$other)?>"></label></div><?php
    }
    public static function signature(string $field,string $title,array $state,string $base): void {
        if(self::$paperEntry){$e=[PDSEditorView::class,'e'];echo '<div class="pe-paper-signature"><p class="pe-help">Upload a clear photo or scan of the signature already on the authorized paper form. Enter the date written on the paper; leave it blank if none is recorded.</p>';PDSEditorView::media($field,$title.' photo',$state,$base);echo '<label class="pe-consent-check"><input type="checkbox" name="'.$field.'_confirm" value="1"> I confirm this is a copy of the '.($field==='parent_signature'?'parent/guardian':'student').' signature on the authorized paper form.</label></div>';return;}
        $e=[PDSEditorView::class,'e'];?><div class="pe-signature-pad data-signature="<?=$field?>"><p class="pe-help"><?=$e($title)?>: draw below with a mouse, finger or stylus. The pad starts blank and never copies your saved signature.</p><canvas aria-label="<?=$e($title)?> drawing area" tabindex="0"></canvas><div class="pe-signature-actions"><button type="button" class="pe-button" data-signature-clear>Clear Signature</button><button type="button" class="pe-button" data-signature-undo>Undo</button></div><div class="pe-signature-preview"><span>Live preview</span><img data-signature-live alt="New handwritten signature preview" hidden></div><input type="hidden" name="<?=$field?>_drawn" value=""><label class="pe-signature-consent"><input type="checkbox" name="<?=$field?>_confirm" value="1"> I am the <?=$field==='parent_signature'?'parent/guardian signer':'signer'?> and authorize this new signature to be applied to this PDS.</label><button type="button" class="pe-button" data-signature-save>Save Signature</button><p data-signature-status class="pe-help" role="status">Save Signature confirms the drawing in this form. Save PDS applies it to your record and paper form.</p><details class="pe-signature-upload"><summary>Or upload a signature image / view the saved image</summary><?php PDSEditorView::media($field,$title.' image',$state,$base);?></details></div><?php
    }
}
